import yaml
import os
import sqlite3
import pandas as pd
import time
from typing import List, Dict, Any, Optional

YAML_PATH = os.path.join(os.path.dirname(__file__), "metrics.yaml")
DB_PATH = os.path.join(os.path.dirname(os.path.dirname(__file__)), "database", "warehouse.db")

class SemanticCompiler:
    def __init__(self):
        with open(YAML_PATH, "r") as f:
            self.schema = yaml.safe_load(f)
        self.metrics_def = self.schema.get("metrics", {})
        self.dimensions_def = self.schema.get("dimensions", {})
        self.primary_table = self.schema.get("table_mapping", {}).get("primary_table", "fact_enterprise_sales")

    def get_registered_metrics(self) -> Dict[str, Any]:
        return self.metrics_def

    def get_registered_dimensions(self) -> Dict[str, Any]:
        return self.dimensions_def

    def compile_and_execute(
        self,
        measures: List[str],
        dimensions: Optional[List[str]] = None,
        filters: Optional[Dict[str, Any]] = None,
        order_by: Optional[str] = None,
        limit: int = 100
    ) -> Dict[str, Any]:
        start_time = time.time()
        dimensions = dimensions or []
        filters = filters or {}

        # 1. Validate Measures & Build Select Expressions
        select_exprs = []

        # Add dimensions to select
        for dim in dimensions:
            if dim not in self.dimensions_def:
                raise ValueError(f"Unknown dimension: '{dim}'. Must be one of {list(self.dimensions_def.keys())}")
            col_name = self.dimensions_def[dim]["column"]
            select_exprs.append(f"{col_name} AS {dim}")

        # Add measures to select
        for m in measures:
            if m not in self.metrics_def:
                raise ValueError(f"Unknown metric/measure: '{m}'. Must be one of {list(self.metrics_def.keys())}")
            m_info = self.metrics_def[m]

            if "sql_formula" in m_info:
                select_exprs.append(f"{m_info['sql_formula']} AS {m}")
            elif m_info.get("type") == "measure":
                agg = m_info["aggregation"]
                col = m_info["column"]
                select_exprs.append(f"{agg}({col}) AS {m}")
            else:
                select_exprs.append(f"SUM({m}) AS {m}")

        # 2. Build Where Clause (Filters)
        where_clauses = []
        params = []
        for dim_key, val in filters.items():
            if dim_key in self.dimensions_def:
                col_name = self.dimensions_def[dim_key]["column"]
                if isinstance(val, list):
                    placeholders = ",".join(["?"] * len(val))
                    where_clauses.append(f"{col_name} IN ({placeholders})")
                    params.extend(val)
                else:
                    where_clauses.append(f"{col_name} = ?")
                    params.append(val)

        where_sql = ""
        if where_clauses:
            where_sql = "WHERE " + " AND ".join(where_clauses)

        # 3. Build Group By Clause
        group_by_sql = ""
        if dimensions:
            dim_cols = [self.dimensions_def[d]["column"] for d in dimensions]
            group_by_sql = "GROUP BY " + ", ".join(dim_cols)

        # 4. Build Order By Clause
        order_sql = ""
        if order_by:
            order_sql = f"ORDER BY {order_by}"
        elif dimensions:
            order_sql = f"ORDER BY {dimensions[0]} ASC"

        # 5. Assemble Final Governed SQL
        sql_query = f"""
SELECT
    {', '.join(select_exprs)}
FROM {self.primary_table}
{where_sql}
{group_by_sql}
{order_sql}
LIMIT {min(limit, 500)}
""".strip()

        # 6. Execute against Warehouse DB
        if not os.path.exists(DB_PATH):
            from database.warehouse import init_warehouse_db
            init_warehouse_db()

        conn = sqlite3.connect(DB_PATH)
        try:
            df = pd.read_sql_query(sql_query, conn, params=params)

            # Post-process rounding for percentages & monetary amounts
            for col in df.columns:
                if col in self.metrics_def:
                    fmt = self.metrics_def[col].get("format")
                    if fmt in ["percentage", "currency"]:
                        df[col] = df[col].round(2)

            data_records = df.to_dict(orient="records")
            exec_time = round((time.time() - start_time) * 1000, 2)

            return {
                "status": "success",
                "sql_query": sql_query,
                "params": params,
                "row_count": len(data_records),
                "execution_time_ms": exec_time,
                "data": data_records,
                "semantic_payload": {
                    "measures": measures,
                    "dimensions": dimensions,
                    "filters": filters
                }
            }
        except Exception as e:
            return {
                "status": "error",
                "sql_query": sql_query,
                "error": str(e)
            }
        finally:
            conn.close()

