import React, { useState } from 'react';
import { Cpu, CheckCircle2, ChevronDown, ChevronUp, Sparkles, Workflow } from 'lucide-react';

export default function ThoughtStream({ steps, executionTimeMs }) {
  const [expanded, setExpanded] = useState(true);

  if (!steps || steps.length === 0) return null;

  return (
    <div className="mb-6 rounded-xl border border-purple-500/30 bg-purple-950/20 overflow-hidden transition-all shadow-lg shadow-purple-950/30">
      {/* Stream Header */}
      <div 
        onClick={() => setExpanded(!expanded)}
        className="px-4 py-3 bg-purple-900/30 border-b border-purple-500/20 flex items-center justify-between cursor-pointer hover:bg-purple-900/40 transition-colors"
      >
        <div className="flex items-center space-x-2.5">
          <div className="p-1.5 rounded-lg bg-purple-500/20 text-purple-400">
            <Workflow className="h-4 w-4 animate-pulse" />
          </div>
          <div>
            <span className="text-xs font-semibold text-purple-200 tracking-wide uppercase">
              Agentic Orchestration Thought Stream
            </span>
            <p className="text-[11px] text-purple-300/70">
              Multi-Step Reasoning & Semantic Compiler Execution ({executionTimeMs || 24}ms)
            </p>
          </div>
        </div>

        <div className="flex items-center space-x-2 text-purple-300 text-xs">
          <span className="px-2 py-0.5 rounded bg-purple-500/20 text-[10px] font-mono border border-purple-400/20">
            {steps.length} Steps Completed
          </span>
          {expanded ? <ChevronUp className="h-4 w-4" /> : <ChevronDown className="h-4 w-4" />}
        </div>
      </div>

      {/* Stream Body */}
      {expanded && (
        <div className="p-4 space-y-3 font-mono text-xs">
          {steps.map((stepItem, idx) => (
            <div key={idx} className="flex items-start space-x-3 bg-slate-950/60 p-3 rounded-lg border border-purple-500/10">
              <div className="mt-0.5 text-emerald-400">
                <CheckCircle2 className="h-4 w-4" />
              </div>
              <div className="flex-1 space-y-1">
                <div className="flex items-center justify-between">
                  <span className="font-semibold text-purple-300">
                    Step {stepItem.step}: {stepItem.title}
                  </span>
                  <span className="text-[10px] text-slate-400">VERIFIED</span>
                </div>
                <p className="text-slate-300 leading-relaxed font-sans text-[12px]">
                  {stepItem.detail}
                </p>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

