export default function TransparencyDrawer({ isOpen, onClose, transparencyData }) {
  const [copiedKey, setCopiedKey] = useState(null);
  const [activeView, setActiveView] = useState('sql'); // 'sql' or 'semantic'

  if (!isOpen || !transparencyData) return null;

  const handleCopy = (text, key) => {
    navigator.clipboard.writeText(text);
    setCopiedKey(key);
    setTimeout(() => setCopiedKey(null), 2000);
  };

  const sqlQuery = transparencyData.compiled_sql || transparencyData.sql_query || '-- No SQL generated';
  const semanticCall = JSON.stringify(transparencyData.semantic_call || {}, null, 2);

  return (
