  return (
    <div className="space-y-6">
      {/* Insight Executive Summary Cards */}
      {insights && insights.length > 0 && (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          {insights.map((item, index) => {
            const isWarning = item.status === 'warning' || item.status === 'critical';
            const isSuccess = item.status === 'success';

            return (
              <div 
                key={index}
                className={`p-4 rounded-xl glass-panel border transition-all ${
                  isWarning 
                    ? 'border-rose-500/30 bg-rose-950/20' 
                    : isSuccess 
                      ? 'border-emerald-500/30 bg-emerald-950/20'
                      : 'border-blue-500/30 bg-blue-950/20'
                }`}
              >
                <div className="flex items-start justify-between">
                  <span className="text-xs font-medium text-slate-400">{item.title}</span>
                  {isWarning ? (
                    <AlertTriangle className="h-4 w-4 text-rose-400" />
                  ) : isSuccess ? (
                    <CheckCircle className="h-4 w-4 text-emerald-400" />
                  ) : (
                    <Info className="h-4 w-4 text-blue-400" />
                  )}
                </div>
                <div className="mt-2 flex items-baseline justify-between">
                  <span className="text-2xl font-bold text-white tracking-tight">{item.value}</span>
                  <span className={`text-xs font-semibold px-2 py-0.5 rounded ${
                    isWarning ? 'bg-rose-500/20 text-rose-300' : 'bg-emerald-500/20 text-emerald-300'
