                <Legend wrapperStyle={{ fontSize: '12px' }} />
                <Bar dataKey="revenue" fill="#3B82F6" name="Revenue ($)" radius={[6, 6, 0, 0]} />
                <Bar dataKey="gross_margin_pct" fill="#10B981" name="Gross Margin %" radius={[6, 6, 0, 0]} />
              </BarChart>
