                  <th className="pb-2 font-semibold">Sub-Region</th>
                  <th className="pb-2 font-semibold">Product Line</th>
                  <th className="pb-2 font-semibold">Gross Margin %</th>
                  <th className="pb-2 font-semibold">Shipping Cost ($)</th>
                  <th className="pb-2 font-semibold">Material Cost ($)</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-800/60 font-mono text-slate-300">
                {drilldownData.map((row, i) => (
                  <tr key={i} className="hover:bg-purple-900/20 transition-colors">
                    <td className="py-2.5 font-sans font-medium text-white">{row.sub_region}</td>
                    <td className="py-2.5 font-sans">{row.product_category}</td>
                    <td className={`py-2.5 font-bold ${row.gross_margin_pct < 45 ? 'text-rose-400' : 'text-emerald-400'}`}>
