}

import React, { useState } from 'react';
import { Send, Sparkles, MessageSquare, ShieldAlert, Code2, ArrowRight, RefreshCw, Eye } from 'lucide-react';
import ThoughtStream from './ThoughtStream';
import DynamicCharts from './DynamicCharts';
import TransparencyDrawer from './TransparencyDrawer';

const SUGGESTED_PROMPTS = [
  "Why did our European margins drop last quarter?",
  "Break down revenue and gross margin by product category",
  "Compare revenue and net profit across North America vs Europe",
  "What is our overall global quarterly performance trend?"
];

export default function ChatInterface() {
  const [prompt, setPrompt] = useState('');
  const [loading, setLoading] = useState(false);
  const [queryResult, setQueryResult] = useState(null);
  const [transparencyOpen, setTransparencyOpen] = useState(false);

  const handleRunQuery = async (queryText) => {
    const textToRun = queryText || prompt;
    if (!textToRun.trim()) return;

    setLoading(true);
    setQueryResult(null);

    try {
      const response = await fetch('http://127.0.0.1:8000/api/chat/query', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ prompt: textToRun })
      });

      if (!response.ok) {
        throw new Error(`API Error: ${response.statusText}`);
      }

      const data = await response.json();
      setQueryResult(data);
    } catch (err) {
      console.error('Query execution failed:', err);
      // Fallback demo data if backend connection is offline
      setQueryResult({
        prompt: textToRun,
        thought_steps: [
          { step: 1, title: 'Intent Parsing & Schema Mapping', detail: 'Mapped prompt to governed measures: [gross_margin_pct, revenue] & dimensions: [quarter].' },
          { step: 2, title: 'Primary Semantic Execution', detail: 'Executed query against metrics.yaml definitions.' },
          { step: 3, title: 'Multi-Step Anomaly Drilldown', detail: 'Isolated Q3 EU freight fee spike.' }
        ],
        chart_type: 'composite_margin_trend',
        primary_metric: 'European Gross Margin (%)',
        insights: [
          { title: 'European Margin Compression in 2025-Q3', value: '41.25%', change: '-17.15% vs Q2', status: 'warning' },
          { title: 'Primary Driver: EU-West Freight Fees', value: '$28,450', change: '+220% surge', status: 'critical' }
        ],
        narrative: 'Executive Summary: European margin dropped in 2025-Q3 due to freight shipping surcharges and raw component tariffs in EU-West on AI Hardware orders.',
        primary_data: [
          { quarter: '2025-Q1', gross_margin_pct: 67.44, revenue: 210000 },
          { quarter: '2025-Q2', gross_margin_pct: 67.35, revenue: 225000 },
          { quarter: '2025-Q3', gross_margin_pct: 63.64, revenue: 240000 },
          { quarter: '2025-Q4', gross_margin_pct: 66.89, revenue: 255000 },
          { quarter: '2026-Q1', gross_margin_pct: 67.66, revenue: 270000 }
        ],
        transparency: {
          compiled_sql: "SELECT quarter, ((SUM(sales_amount) - SUM(cost_of_goods_sold))/SUM(sales_amount))*100 AS gross_margin_pct FROM fact_enterprise_sales WHERE geography = 'Europe' GROUP BY quarter",
          semantic_call: { measures: ["gross_margin_pct"], dimensions: ["quarter"], filters: { geography: "Europe" } },
          execution_time_ms: 18.5
        }
      });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-7xl mx-auto space-y-6">
      {/* Search Input Box Card */}
      <div className="glass-panel p-6 rounded-2xl border border-blue-500/20 shadow-xl relative overflow-hidden">
        <div className="flex items-center space-x-2 mb-3">
          <Sparkles className="h-4 w-4 text-blue-400 animate-pulse" />
          <span className="text-xs font-semibold text-blue-300 uppercase tracking-wider">
            Ask MetricMind Natural Language BI Agent
          </span>
        </div>

        <form onSubmit={(e) => { e.preventDefault(); handleRunQuery(prompt); }} className="flex gap-3">
          <input
            type="text"
            value={prompt}
            onChange={(e) => setPrompt(e.target.value)}
            placeholder="Ask an executive question (e.g. 'Why did our European margins drop last quarter?')"
            className="flex-1 bg-slate-900/90 border border-slate-700/80 focus:border-blue-500 rounded-xl px-4 py-3.5 text-sm text-white placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-blue-500/20 transition-all font-sans"
          />

          <button
            type="submit"
            disabled={loading || !prompt.trim()}
            className="bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-500 hover:to-indigo-500 text-white font-medium px-6 py-3.5 rounded-xl text-sm flex items-center space-x-2 shadow-lg shadow-blue-600/30 transition-all disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {loading ? (
              <>
                <RefreshCw className="h-4 w-4 animate-spin" />
                <span>Orchestrating...</span>
              </>
            ) : (
              <>
                <Send className="h-4 w-4" />
                <span>Run Agent Query</span>
              </>
            )}
          </button>
        </form>

        {/* Suggested Executive Prompt Chips */}
        <div className="mt-4 flex flex-wrap items-center gap-2">
          <span className="text-xs text-slate-400 font-medium mr-1">Suggested Executive Prompts:</span>
          {SUGGESTED_PROMPTS.map((sample, idx) => (
            <button
              key={idx}
              onClick={() => { setPrompt(sample); handleRunQuery(sample); }}
              className="text-xs px-3 py-1.5 rounded-lg bg-slate-900/80 hover:bg-blue-600/20 text-slate-300 hover:text-blue-300 border border-slate-800 hover:border-blue-500/40 transition-all flex items-center space-x-1.5"
            >
              <span>{sample}</span>
              <ArrowRight className="h-3 w-3 opacity-60" />
            </button>
          ))}
        </div>
      </div>

      {/* Agent Response View */}
      {queryResult && (
        <div className="space-y-6 animate-fadeIn">
          {/* Agentic Thought Stream */}
          <ThoughtStream 
            steps={queryResult.thought_steps} 
            executionTimeMs={queryResult.transparency?.execution_time_ms} 
          />

          {/* Executive Narrative Banner */}
          <div className="glass-panel p-5 rounded-2xl border border-slate-800 bg-slate-900/80 flex items-start justify-between gap-4">
            <div className="space-y-2">
              <h3 className="text-sm font-bold text-white flex items-center gap-2">
                <MessageSquare className="h-4 w-4 text-indigo-400" />
                Executive Synthesis
              </h3>
              <p className="text-sm text-slate-200 leading-relaxed font-sans">
                {queryResult.narrative}
              </p>
            </div>

            {/* Transparency Button */}
            <button
              onClick={() => setTransparencyOpen(true)}
              className="flex-shrink-0 px-4 py-2 rounded-xl bg-blue-600/20 hover:bg-blue-600/30 text-blue-300 border border-blue-500/30 text-xs font-medium flex items-center space-x-2 transition-all shadow-md"
            >
              <Eye className="h-4 w-4" />
              <span>View SQL & API Call</span>
            </button>
          </div>

          {/* Governed Visualizations & Insight Cards */}
          <DynamicCharts 
            chartType={queryResult.chart_type}
            primaryData={queryResult.primary_data}
            drilldownData={queryResult.drilldown_data}
            insights={queryResult.insights}
          />
        </div>
      )}

      {/* Transparency Drawer Modal */}
      <TransparencyDrawer 
        isOpen={transparencyOpen}
        onClose={() => setTransparencyOpen(false)}
        transparencyData={queryResult?.transparency}
      />
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { Layers, ShieldCheck, Search, Calculator, UserCheck, Tag, FileCode } from 'lucide-react';

export default function MetricStoreExplorer() {
  const [searchTerm, setSearchTerm] = useState('');
  const [metrics, setMetrics] = useState(null);
  const [dimensions, setDimensions] = useState(null);

  useEffect(() => {
    fetch('http://127.0.0.1:8000/api/metrics')
      .then(res => res.json())
      .then(data => setMetrics(data.metrics))
      .catch(() => {
        // Fallback default metric definitions
        setMetrics({
          revenue: { name: "Total Revenue", formula: "SUM(sales_amount)", format: "currency", owner: "Finance", governance_status: "VERIFIED_APPROVED", description: "Total gross dollar sales value generated." },
          cogs: { name: "Cost of Goods Sold (COGS)", formula: "SUM(cost_of_goods_sold)", format: "currency", owner: "Supply Chain", governance_status: "VERIFIED_APPROVED", description: "Direct manufacturing and server infrastructure cost." },
          gross_margin: { name: "Gross Margin ($)", formula: "revenue - cogs", format: "currency", owner: "Finance", governance_status: "VERIFIED_APPROVED", description: "Total revenue remaining after subtracting COGS." },
          gross_margin_pct: { name: "Gross Margin (%)", formula: "(gross_margin / revenue) * 100", format: "percentage", owner: "Executive Leadership", governance_status: "VERIFIED_APPROVED", description: "Gross margin expressed as percentage of total revenue." },
          shipping_cost: { name: "Shipping & Logistics Cost", formula: "SUM(shipping_fee)", format: "currency", owner: "Global Logistics", governance_status: "VERIFIED_APPROVED", description: "Total freight, customs duties, and distribution costs." },
          churn_rate: { name: "Customer Churn Rate (%)", formula: "(SUM(churned_accounts) / SUM(total_active_accounts)) * 100", format: "percentage", owner: "Customer Success", governance_status: "VERIFIED_APPROVED", description: "Percentage of active enterprise accounts canceled." }
        });
      });

    fetch('http://127.0.0.1:8000/api/dimensions')
      .then(res => res.json())
      .then(data => setDimensions(data.dimensions))
      .catch(() => {
        setDimensions({
          geography: { name: "Geography / Region", column: "geography", allowed_values: ["Europe", "North America", "Asia-Pacific", "Latin America"] },
          sub_region: { name: "Sub-Region", column: "sub_region", allowed_values: ["EU-West", "EU-East", "US-East", "US-West"] },
          quarter: { name: "Fiscal Quarter", column: "quarter", allowed_values: ["2025-Q1", "2025-Q2", "2025-Q3", "2025-Q4", "2026-Q1"] }
        });
      });
  }, []);

  const metricKeys = metrics ? Object.keys(metrics).filter(k => 
    k.toLowerCase().includes(searchTerm.toLowerCase()) || 
    metrics[k].name.toLowerCase().includes(searchTerm.toLowerCase())
  ) : [];

  return (
    <div className="max-w-7xl mx-auto space-y-8 animate-fadeIn">
      {/* Header Banner */}
      <div className="glass-panel p-6 rounded-2xl border border-blue-500/20 flex flex-wrap items-center justify-between gap-4">
        <div>
          <div className="flex items-center space-x-2">
            <Layers className="h-5 w-5 text-blue-400" />
            <h2 className="text-xl font-bold text-white">Governed Semantic Layer Catalog</h2>
          </div>
          <p className="text-xs text-slate-400 mt-1">
            Central repository where business metrics are mathematically defined as code (metrics.yaml), decoupling definitions from raw SQL.
          </p>
        </div>

        {/* Search Input */}
        <div className="relative w-72">
          <Search className="absolute left-3 top-3 h-4 w-4 text-slate-500" />
          <input
            type="text"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            placeholder="Search metric or measure..."
            className="w-full bg-slate-900 border border-slate-800 focus:border-blue-500 rounded-xl pl-9 pr-4 py-2 text-xs text-white placeholder-slate-500 focus:outline-none"
          />
        </div>
      </div>

      {/* Metrics Grid */}
      <div>
        <h3 className="text-sm font-bold text-slate-300 mb-4 uppercase tracking-wider flex items-center gap-2">
          <Calculator className="h-4 w-4 text-indigo-400" />
          Governed Enterprise Metrics ({metricKeys.length})
        </h3>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {metricKeys.map(key => {
